import * as THREE from 'three';
// Sky dome: two-stop vertical gradient by view direction, drawn behind everything and following the camera.
export function makeSky(zenith = 0x0d1b2e, horizon = 0x2f5d8c, radius = 900) {
  const mat = new THREE.ShaderMaterial({
    side: THREE.BackSide, depthWrite: false, fog: false,
    uniforms: { uZenith: { value: new THREE.Color(zenith) }, uHorizon: { value: new THREE.Color(horizon) } },
    vertexShader: 'varying vec3 vDir; void main(){ vDir = normalize(position); gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0); gl_Position.z = gl_Position.w; }',
    fragmentShader: [
      'uniform vec3 uZenith, uHorizon; varying vec3 vDir;',
      'void main(){ float t = pow(clamp(vDir.y, 0.0, 1.0), 0.6);   // haze band hugs the horizon',
      '  gl_FragColor = vec4(mix(uHorizon, uZenith, t), 1.0); }'
    ].join('\n')
  });
  const dome = new THREE.Mesh(new THREE.SphereGeometry(radius, 32, 16), mat);
  dome.userData.tag = 'sky'; dome.frustumCulled = false; dome.renderOrder = -1;
  return dome;
}
export function tickSky(dome, camera) { dome.position.copy(camera.position); }
